-- Errata reading for O08: Age = latest reported age (most recent demographic_updates age_reported received by the as-of date, else the roster age_reported); everything else as the reference.
WITH r AS MATERIALIZED (SELECT patient, stream, payload FROM records WHERE stream IN ('conditions','pharmacy_dispenses')), dm AS (SELECT DISTINCT patient FROM (SELECT patient, lower(coalesce(json_extract(payload,'$.description'),'')) d, coalesce(json_extract(payload,'$.icd10'),'') i FROM r WHERE stream='conditions') WHERE (d LIKE '%diabet%' OR d LIKE 't1dm%' OR d LIKE 't2dm%' OR i LIKE 'E10%' OR i LIKE 'E11%') AND d NOT LIKE '%prediabet%' AND d NOT LIKE '%family history%' AND d NOT LIKE 'gdm%' AND i NOT LIKE 'O24%' AND i NOT LIKE 'Z83%'), st AS (SELECT DISTINCT patient FROM r WHERE stream='pharmacy_dispenses' AND json_extract(payload,'$.status')='dispensed' AND json_extract(payload,'$.event_date') BETWEEN '2028-01-01' AND '2029-08-15' AND lower(json_extract(payload,'$.medication_name')) LIKE '%statin%') SELECT COUNT(*) AS count FROM patients p JOIN dm ON dm.patient=p.id WHERE json_extract(p.payload,'$.sex_reported')='M' AND coalesce((SELECT json_extract(du_.payload,'$.age_reported') FROM records du_ WHERE du_.stream='demographic_updates' AND du_.patient=p.id AND json_extract(du_.payload,'$.age_reported') IS NOT NULL ORDER BY json_extract(du_.payload,'$.age_reference_date') DESC LIMIT 1), json_extract(p.payload,'$.age_reported')) BETWEEN 40 AND 75 AND p.id NOT IN (SELECT patient FROM st);
